function renderQuotesList(){const arr=state.quotes.slice(0,80);$('#quotes-count').textContent=arr.length;$('#quotes-list').innerHTML=arr.map(q=>{const c=clientById(q.client_id);const total=q.negotiated_total??q.original_total;return `<div class="work-item"><div class="work-main"><b>${esc(q.quote_number||q.title||'Orçamento')} · ${esc(c?.name||'Cliente')}</b><span>${localDate(q.created_at)} · ${money(total)}</span></div><div class="work-meta"><span class="badge ${q.status==='aprovado'?'green':q.status==='recusado'?'':'orange'}">${esc(q.status)}</span></div><div class="work-actions"><button class="mini-button primary" data-load-quote="${q.id}">Abrir</button></div></div>`}).join('')||empty('Nenhum orçamento salvo.') ;$$('[data-load-quote]').forEach(b=>b.onclick=()=>loadQuote(b.dataset.loadQuote))}
