async function uploadMedia(file,folder='orders'){if(!file)return null;if(state.demo)return await fileToData(file);const ext=(file.name.split('.').pop()||'jpg').toLowerCase();const path=`${folder}/${new Date().getFullYear()}/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;const {error}=await state.supabase.storage.from('valtec-media').upload(path,file,{upsert:false,contentType:file.type});if(error)throw error;return state.supabase.storage.from('valtec-media').getPublicUrl(path).data.publicUrl}
