async function savePart(e){e.preventDefault();const id=$('#part-id').value;const payload={name:$('#part-name').value.trim(),category:$('#part-category').value.trim()||'Outros',brand:$('#part-brand').value.trim()||null,code:$('#part-code').value.trim()||null,aliases:$('#part-aliases').value.split(',').map(x=>x.trim()).filter(Boolean),purchase_price:Number($('#part-buy-price').value)||0,sale_price:Number($('#part-sale-price').value)||0,stock_qty:Number($('#part-stock').value)||0,min_stock:Number($('#part-min-stock').value)||0,image_url:$('#part-image-url').value.trim()||null,source_url:$('#part-source-url').value.trim()||null,active:true,updated_at:new Date().toISOString()};if(state.demo){if(id)Object.assign(state.parts.find(x=>x.id===id),payload);else state.parts.push({id:uid(),...payload});$('#part-form').classList.add('hidden');renderAll();return flash('Peça salva na demonstração.')}const res=id?await state.supabase.from('parts_catalog').update(payload).eq('id',id).select().single():await state.supabase.from('parts_catalog').insert(payload).select().single();if(res.error)return flash('Não foi possível salvar a peça.','error');if(payload.image_url){const exists=state.images.some(i=>i.image_url===payload.image_url);if(!exists)await state.supabase.from('image_assets').insert({name:payload.name,category:payload.category,aliases:payload.aliases,image_url:payload.image_url,source_url:payload.source_url,source_kind:payload.source_url==='Foto própria Valtec'?'upload':'web'})}await audit(id?'atualizou':'criou','peca',res.data.id,{name:res.data.name,stock:res.data.stock_qty});$('#part-form').classList.add('hidden');await loadAll();renderAll();flash('Peça salva no catálogo.')}
function imageMode(mode){if(mode==='web')openImagePicker($('#part-name').value);if(mode==='bank')openBankImages();if(mode==='url'){$('#part-image-url').focus()}}
function openImagePicker(q=''){$('#image-picker').classList.remove('hidden');$('#web-image-query').value=q||$('#part-name').value||'';$('#web-image-results').innerHTML=empty('Digite o nome da peça e clique em pesquisar.')}
function openBankImages(){$('#image-picker').classList.remove('hidden');$('#web-image-query').value='Banco Valtec';const unique=[...state.images,...state.parts.filter(p=>p.image_url).map(p=>({id:'part-'+p.id,name:p.name,image_url:p.image_url,source_url:p.source_url,source_kind:'catálogo'}))].filter((x,i,a)=>x.image_url&&a.findIndex(y=>y.image_url===x.image_url)===i);renderImageResults(unique.slice(0,80))}
async function searchWebImages(){const q=$('#web-image-query').value.trim();if(!q)return;$('#web-image-results').innerHTML=empty('Buscando imagens com fonte…');try{const url=`https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=${encodeURIComponent(q)}&gsrnamespace=6&gsrlimit=24&prop=imageinfo&iiprop=url|extmetadata&iiurlwidth=500&format=json&origin=*`;const res=await fetch(url);const json=await res.json();const items=Object.values(json.query?.pages||{}).map(p=>({name:p.title?.replace(/^File:/,'')||q,image_url:p.imageinfo?.[0]?.thumburl||p.imageinfo?.[0]?.url,source_url:p.imageinfo?.[0]?.descriptionurl||`https://commons.wikimedia.org/wiki/${encodeURIComponent(p.title||'')}`,source_kind:'Wikimedia Commons',license:p.imageinfo?.[0]?.extmetadata?.LicenseShortName?.value||''})).filter(x=>x.image_url);renderImageResults(items)}catch{$('#web-image-results').innerHTML=empty('A busca não respondeu. Use o botão Google Imagens e cole o link/fonte da imagem escolhida.') }}
function renderImageResults(items){$('#web-image-results').innerHTML=items.map((x,i)=>`<article class="web-image-card"><img src="${esc(x.image_url)}" alt=""><div><b>${esc(x.name||'Imagem')}</b><small>${esc(x.source_kind||'Banco Valtec')} ${x.license?'· '+esc(x.license):''}</small><button data-pick-image="${i}">Usar esta imagem</button></div></article>`).join('')||empty('Nenhuma imagem encontrada.');$$('[data-pick-image]').forEach(b=>b.onclick=()=>{const x=items[Number(b.dataset.pickImage)];$('#part-image-url').value=x.image_url;$('#part-source-url').value=x.source_url||'';renderSelectedImage();$('#image-picker').classList.add('hidden');$('#part-form').classList.remove('hidden')})}

function renderFinance(){const now=new Date(),ym=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;const rec=state.receipts.filter(r=>String(r.issued_at||'').startsWith(ym)).reduce((a,r)=>a+Number(r.amount||0),0);const pend=state.orders.filter(o=>o.payment_status!=='pago').reduce((a,o)=>a+Number(o.total_amount||0),0);const exp=state.expenses.filter(e=>String(e.occurred_on||'').startsWith(ym)).reduce((a,e)=>a+Number(e.amount||0),0);$('#finance-received').textContent=money(rec);$('#finance-pending').textContent=money(pend);$('#finance-expenses').textContent=money(exp);$('#finance-balance').textContent=money(rec-exp);$('#finance-orders').innerHTML=state.orders.slice(0,40).map(o=>{const c=orderClient(o);return `<div class="work-item"><div class="work-main"><b>${esc(c.name)} · ${esc(o.order_number||'OS')}</b><span>${esc(o.payment_status||'pendente')} · ${esc(o.payment_method||'')}</span></div><div class="work-meta">${money(o.total_amount)}</div><div></div></div>`}).join('')||empty('Nenhum serviço financeiro.');$('#expenses-list').innerHTML=state.expenses.slice(0,40).map(e=>`<div class="work-item"><div class="work-main"><b>${esc(e.description)}</b><span>${esc(e.category)} · ${localDate(e.occurred_on)}</span></div><div class="work-meta">${money(e.amount)}</div><div></div></div>`).join('')||empty('Nenhum gasto registrado.')}
async function saveExpense(e){e.preventDefault();const payload={category:$('#expense-category').value,description:$('#expense-description').value.trim(),amount:Number($('#expense-amount').value)||0,occurred_on:$('#expense-date').value||isoDate()};if(state.demo){state.expenses.unshift({id:uid(),...payload});$('#expense-form').classList.add('hidden');renderAll();return flash('Gasto salvo na demonstração.')}const {data,error}=await state.supabase.from('expenses').insert(payload).select().single();if(error)return flash('Não foi possível salvar o gasto.','error');await audit('criou','despesa',data.id,{amount:data.amount,description:data.description});$('#expense-form').classList.add('hidden');await loadAll();renderAll();flash('Gasto registrado.')}
function renderWarranties(){const now=new Date();state.warranties.forEach(w=>{if(w.status==='ativa'&&new Date(w.ends_at+'T23:59:00')<now)w.status='expirada'});$('#warranties-list').innerHTML=state.warranties.map(w=>{const c=clientById(w.client_id);const o=state.orders.find(x=>x.id===w.service_order_id);return `<div class="work-item"><div class="work-main"><b>${esc(c?.name||'Cliente')} · ${esc(o?.order_number||'OS')}</b><span>${esc(o?.equipment||'Serviço')} · ${esc(w.notes||'')}</span></div><div class="work-meta">Até ${localDate(w.ends_at)}</div><div class="work-actions"><span class="badge ${w.status==='ativa'?'green':''}">${esc(w.status)}</span></div></div>`}).join('')||empty('Nenhuma garantia registrada.')}
function renderMarketing(){const visits=state.events.filter(e=>e.event_name==='page_view').length,checks=state.events.filter(e=>e.event_name==='neighborhood_check').length,wa=state.events.filter(e=>e.event_name==='whatsapp_click').length;$('#marketing-visits').textContent=visits;$('#marketing-checks').textContent=checks;$('#marketing-leads').textContent=state.leads.length;$('#marketing-whatsapp').textContent=wa;const counts={};state.events.filter(e=>e.event_name==='neighborhood_check').forEach(e=>{const n=e.neighborhood||e.metadata?.neighborhood;if(n)counts[n]=(counts[n]||0)+1});$('#marketing-neighborhoods').innerHTML=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([n,c],i)=>`<div class="summary-row"><span>${i+1}. ${esc(n)}</span><strong>${c}</strong></div>`).join('')||'<p class="muted">Os bairros aparecem conforme as pessoas consultam o site.</p>';const seo=JSON.parse(localStorage.getItem('valtec_seo_checks')||'{}');$('#seo-search-console-check').checked=!!seo.searchConsole;$('#seo-business-check').checked=!!seo.businessProfile;let cfg=$('#marketing-config');if(!cfg){cfg=document.createElement('div');cfg.id='marketing-config';cfg.className='panel list-panel';cfg.innerHTML=`<span class="kicker">Links oficiais</span><h2>Google e Instagram</h2><div class="choice-grid"><div class="field"><label>Link direto para avaliação no Google</label><input id="google-review-url" class="input" placeholder="Cole o link de solicitar avaliação"></div><div class="field"><label>Instagram</label><input id="instagram-url" class="input" value="https://www.instagram.com/valtec_solucoess/"></div></div><button id="save-marketing-links" class="btn btn-primary">Salvar links</button>`;const panel=$('[data-tab-panel="marketing"]');panel.appendChild(cfg);$('#save-marketing-links').onclick=saveMarketingLinks}$('#google-review-url').value=state.settings.business?.google_review_url||'';$('#instagram-url').value=state.settings.business?.instagram||'https://www.instagram.com/valtec_solucoess/' }
function saveSeoChecks(){localStorage.setItem('valtec_seo_checks',JSON.stringify({searchConsole:$('#seo-search-console-check').checked,businessProfile:$('#seo-business-check').checked}))}
async function saveMarketingLinks(){const current={...(state.settings.business||{}),google_review_url:$('#google-review-url').value.trim(),instagram:$('#instagram-url').value.trim()};if(state.demo){state.settings.business=current;return flash('Links salvos na demonstração.')}const {error}=await state.supabase.from('site_settings').upsert({key:'business',value:current,updated_at:new Date().toISOString()});if(error)return flash('Não foi possível salvar os links.','error');state.settings.business=current;flash('Links de marketing salvos.')}
function renderTeam(){$('#team-list').innerHTML=state.team.map(u=>`<div class="work-item"><div class="work-main"><b>${esc(u.display_name||'Administrador')}</b><span>${esc(u.email||'')} · ${u.active?'Acesso ativo':'Desativado'}</span></div><div><select class="input compact role-select" data-role-user="${u.user_id}"><option value="operacao_admin" ${u.role==='operacao_admin'?'selected':''}>Operação/Admin</option><option value="marketing_admin" ${u.role==='marketing_admin'?'selected':''}>Marketing/Admin</option><option value="operacao" ${u.role==='operacao'?'selected':''}>Operação</option><option value="marketing" ${u.role==='marketing'?'selected':''}>Marketing</option></select></div></div>`).join('')||empty('Nenhum usuário encontrado.');$$('[data-role-user]').forEach(s=>s.onchange=()=>changeRole(s.dataset.roleUser,s.value))}
async function changeRole(id,role){if(state.demo){const u=state.team.find(x=>x.user_id===id);if(u)u.role=role;return flash('Função alterada na demonstração.')}const {error}=await state.supabase.from('admin_profiles').update({role}).eq('user_id',id);if(error)return flash('Não foi possível alterar a função.','error');await audit('alterou_funcao','usuario',id,{role});flash('Função atualizada.')}
function renderAudit(){$('#audit-list').innerHTML=state.audit.map(a=>`<div class="work-item"><div class="work-main"><b>${esc(a.action)} · ${esc(a.entity_type)}</b><span>${localDateTime(a.created_at)}</span></div><div class="audit-detail">${esc(a.entity_id||'')}</div><div></div></div>`).join('')||empty('O histórico começa a ser registrado a partir das novas alterações.')}
async function audit(action,entity_type,entity_id,details={}){if(state.demo){state.audit.unshift({id:uid(),action,entity_type,entity_id,details,created_at:new Date().toISOString()});return}try{const {data}=await state.supabase.auth.getUser();await state.supabase.from('admin_audit_log').insert({actor_id:data?.user?.id||null,action,entity_type,entity_id:String(entity_id||''),details})}catch{}}

document.addEventListener('DOMContentLoaded',init);
